import zipfile, json, sys, os

def load_flpkg(flpath):
    if not zipfile.is_zipfile(flpath):
        print(f"{flpath} is not a valid .flpkg package")
        return

    with zipfile.ZipFile(flpath, 'r') as z:
        if 'manifest.json' not in z.namelist():
            print("No manifest.json found.")
            return

        manifest = json.loads(z.read('manifest.json').decode('utf-8'))
        print(f"=== Manifest ===")
        print(json.dumps(manifest, indent=2, ensure_ascii=False))

        entry_id = None
        entry_source = None
        if 'routing' in manifest and 'entry' in manifest['routing']:
            entry_id = manifest['routing']['entry']

        if entry_id and 'modules' in manifest:
            for mod in manifest['modules']:
                if mod.get('id') == entry_id or mod.get('label') == entry_id:
                    entry_source = mod.get('source')
                    break
        # If entry was a filename instead of id
        if not entry_source:
            for mod in manifest.get('modules', []):
                if mod.get('source') == entry_id:
                    entry_source = entry_id
                    break

        if not entry_source and 'modules' in manifest:
            # fallback: take first module
            entry_source = manifest['modules'][0].get('source')

        if entry_source and entry_source in z.namelist():
            print(f"\n=== Entry Module Content ({entry_source}) ===")
            try:
                content = z.read(entry_source).decode('utf-8')
            except UnicodeDecodeError:
                content = z.read(entry_source).decode('utf-16', errors='ignore')
            print(content)
        else:
            print("\nNo entry source found or file missing in package.")

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python loader.py <package.flpkg>")
        sys.exit(1)
    load_flpkg(sys.argv[1])

