      'pipeline/src/quality.py': `import cv2
import numpy as np

def laplacian_variance(gray):
    """Calculate sharpness using Laplacian variance"""
    return cv2.Laplacian(gray, cv2.CV_64F).var()

def exposure_range(gray):
    """Calculate exposure quality"""
    hist = cv2.calcHist([gray], [0], None, [256], [0, 256]).ravel()
    cdf = np.cumsum(hist) / hist.sum()
    q5 = (cdf > 0.05).argmax() / 255.0
    q95 = (cdf > 0.95).argmax() / 255.0
    return q5, q95

def entropy(gray):
    """Calculate Shannon entropy"""
    hist = cv2.calcHist([gray], [0], None, [256], [0, 256]).ravel()
    p = hist / (hist.sum() + 1e-9)
    p = p[p > 0]
    return -(p * np.log2(p)).sum()

def score(img_bgr):
    """Calculate overall quality score"""
    g = cv2.cvtColor(img_bgr, cv2.COLOR_BGR2GRAY)
    sharp = laplacian_variance(g)
    q5, q95 = exposure_range(g)
    ent = entropy(g)

    s = np.tanh(sharp / 200.0)
    e = np.tanh(ent / 6.0)
    exp_ok = max(0, 1 - (abs(q5 - 0.15) + abs(q95 - 0.95)) / 2)

    total = 0.5 * s + 0.3 * exp_ok + 0.2 * e
    return float(np.clip(total, 0, 1)), {
        "sharp": float(sharp),
        "q5": float(q5),
        "q95": float(q95),
        "entropy": float(ent)
    }`,

      'pipeline/src/attention.py': `import cv2
import numpy as np
from .quality import score

def global_embed(img):
    """Create global image embedding from histograms"""
    g = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    h1 = cv2.calcHist([g], [0], None, [64], [0, 256]).ravel()
    g2 = cv2.resize(g, (128, 128))
    h2 = cv2.calcHist([g2], [0], None, [64], [0, 256]).ravel()
    v = np.concatenate([h1, h2])
    v = v / (np.linalg.norm(v) + 1e-8)
    return v

def attention_select(images_bgr, max_images=120, neighbors=8, blur_thresh=0.35):
    """Select best images using attention mechanism"""
    metas = []
    for idx, img in enumerate(images_bgr):
        s, aux = score(img)
        metas.append({"idx": idx, "score": s, "aux": aux})

    keep = [m for m in metas if m["score"] >= blur_thresh]
    keep_idx = [m["idx"] for m in sorted(keep, key=lambda x: -x["score"])[:max_images]]
    sel = [images_bgr[i] for i in keep_idx]

    embeds = np.stack([global_embed(im) for im in sel], 0)
    sim = embeds @ embeds.T
    np.fill_diagonal(sim, -1)

    A = np.exp(sim) / np.exp(sim).sum(axis=1, keepdims=True)
    neigh_pairs = []
    for i in range(A.shape[0]):
        js = np.argsort(-A[i])[:neighbors]
        for j in js:
            w = float(A[i, j])
            neigh_pairs.append((keep_idx[i], keep_idx[j], w))

    return keep_idx, neigh_pairs, metas`,

