import numpy as np
from .quality import score

def global_embed(img):
    """Create global image embedding from histograms"""
    g = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    h1 = cv2.calcHist([g], [0], None, [64], [0, 256]).ravel()
    g2 = cv2.resize(g, (128, 128))
    h2 = cv2.calcHist([g2], [0], None, [64], [0, 256]).ravel()
    v = np.concatenate([h1, h2])
    v = v / (np.linalg.norm(v) + 1e-8)
    return v

def attention_select(images_bgr, max_images=120, neighbors=8, blur_thresh=0.35):
    """Select best images using attention mechanism"""
    metas = []
    for idx, img in enumerate(images_bgr):
        s, aux = score(img)
        metas.append({"idx": idx, "score": s, "aux": aux})

    keep = [m for m in metas if m["score"] >= blur_thresh]
    keep_idx = [m["idx"] for m in sorted(keep, key=lambda x: -x["score"])[:max_images]]
    sel = [images_bgr[i] for i in keep_idx]

    embeds = np.stack([global_embed(im) for im in sel], 0)
    sim = embeds @ embeds.T
    np.fill_diagonal(sim, -1)

    A = np.exp(sim) / np.exp(sim).sum(axis=1, keepdims=True)
    neigh_pairs = []
    for i in range(A.shape[0]):
        js = np.argsort(-A[i])[:neighbors]
        for j in js:
            w = float(A[i, j])
            neigh_pairs.append((keep_idx[i], keep_idx[j], w))

    return keep_idx, neigh_pairs, metas`,

