      'pipeline/src/quality.py': `import cv2
import numpy as np

def laplacian_variance(gray):
    """Calculate sharpness using Laplacian variance"""
    return cv2.Laplacian(gray, cv2.CV_64F).var()

def exposure_range(gray):
    """Calculate exposure quality"""
    hist = cv2.calcHist([gray], [0], None, [256], [0, 256]).ravel()
    cdf = np.cumsum(hist) / hist.sum()
    q5 = (cdf > 0.05).argmax() / 255.0
    q95 = (cdf > 0.95).argmax() / 255.0
    return q5, q95

def entropy(gray):
    """Calculate Shannon entropy"""
    hist = cv2.calcHist([gray], [0], None, [256], [0, 256]).ravel()
    p = hist / (hist.sum() + 1e-9)
    p = p[p > 0]
    return -(p * np.log2(p)).sum()

def score(img_bgr):
    """Calculate overall quality score"""
    g = cv2.cvtColor(img_bgr, cv2.COLOR_BGR2GRAY)
    sharp = laplacian_variance(g)
    q5, q95 = exposure_range(g)
    ent = entropy(g)

    s = np.tanh(sharp / 200.0)
    e = np.tanh(ent / 6.0)
    exp_ok = max(0, 1 - (abs(q5 - 0.15) + abs(q95 - 0.95)) / 2)

    total = 0.5 * s + 0.3 * exp_ok + 0.2 * e
    return float(np.clip(total, 0, 1)), {
        "sharp": float(sharp),
        "q5": float(q5),
        "q95": float(q95),
        "entropy": float(ent)
    }`,

